	private record IdFilterSpec(Component component, Kind kind) {

		private static IdFilterSpec parse(String token) {
			int separator = token.indexOf(':');
			if (separator <= 0 || separator == token.length() - 1) {
				return null;
			}
			Component component = Component.fromMetric(token.substring(0, separator));
			Kind kind = Kind.fromMetric(token.substring(separator + 1));
			if (component == null || kind == null) {
				return null;
			}
			return new IdFilterSpec(component, kind);
		}
	}

	private static boolean isLiteralId(long id) {
		int type = ValueIds.getIdType(id);
		return type == ValueIds.T_LITERAL || ValueIds.isInlined(id);
	}

	private static boolean acceptsLiteralOrInlinedDatatype(long id, int inlinedType) {
		int type = ValueIds.getIdType(id);
		return type == ValueIds.T_LITERAL || type == inlinedType;
	}
